package com.vynedam.stockai.service; import com.vynedam.stockai.dto.OperationsDtos.ProductRequest; import com.vynedam.stockai.exception.ApiException; import com.vynedam.stockai.model.Product; import com.vynedam.stockai.repository.ProductRepository; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service;
@Service public class ProductService{private final ProductRepository repo;public ProductService(ProductRepository r){repo=r;}public List<Product>list(){return repo.findAll();}public Product get(String id){return repo.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND","Product not found"));}public Product create(ProductRequest r){var p=new Product();p.sku=r.sku().toUpperCase();if(repo.existsBySku(p.sku))throw new ApiException(HttpStatus.CONFLICT,"DUPLICATE_RECORD","Product SKU exists");apply(p,r);return repo.save(p);}public Product update(String id,ProductRequest r){var p=get(id);apply(p,r);return repo.save(p);}private void apply(Product p,ProductRequest r){p.name=r.name();p.category=r.category();p.unit=r.unit();p.reorderPoint=r.reorderPoint()==null?0:r.reorderPoint();}}
